type C02N1Static = StaticRle<2, 3, 8075, 32, C02N0Static>;
#[inline(always)]
fn c02_n1_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    let (run, _, _) = locate_indexed(session, FieldId(3), FieldId(2), 8075, 32, row)?;
    c02_n0_get(session, run)
}

#[inline(always)]
fn c02_n1_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    if start == end { return Ok(()); }
    let (mut run, mut run_start, _) = locate_indexed(session, FieldId(3), FieldId(2), 8075, 32, start)?;
    while run < 8075 && run_start < end {
        let run_end = run_start.checked_add(session.read_u32(FieldId(2), run)? as usize).ok_or("generated RLE row overflow")?;
        let span_start = start.max(run_start);
        let span_end = end.min(run_end);
        if span_start < span_end { let value = c02_n0_get(session, run)?; visitor(session, value, span_start, span_end)?; }
        run_start = run_end; run += 1;
    }
    Ok(())
}

