#[inline(always)]
fn c06_n2_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    match nullable_rank(session, FieldId(1), FieldId(2), row, 256)? {
        Some(compact_row) => c06_n1_get(session, compact_row),
        None => Ok(None),
    }
}

#[inline(always)]
fn c06_n2_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    let mut logical = start; let mut compact = nullable_prefix_rank(session, FieldId(1), FieldId(2), start, 256)?;
    while logical < end { let valid = nullable_is_valid(session, FieldId(1), logical)?; let run_start = logical; logical += 1; while logical < end && nullable_is_valid(session, FieldId(1), logical)? == valid { logical += 1; }
        if valid { let child_start = compact; compact += logical - run_start; c06_n1_visit(session, child_start, compact, &mut |session, value, span_start, span_end| { let mapped_start = run_start + span_start - child_start; visitor(session, value, mapped_start, mapped_start + span_end - span_start) })?; } else { visitor(session, None, run_start, logical)?; }
    } Ok(())
}

pub fn c06_get_session(column: &EncodedColumn, row: usize, session: &mut ReadSession<'_>) -> Result<Execution, String> {
    if row >= column.truth.len() { return Err("generated GET outside column".into()); }
    load_metadata(&column.page, session)?;
    let value = c06_n2_get(session, row)?.map(|value| i64::try_from(value).map_err(|_| "generated GET value does not fit i64")).transpose()?;
    Ok(Execution { answer: Answer::Value(value), metrics: session.metrics(), decoded_rows: 1 })
}

pub fn c06_get(column: &EncodedColumn, row: usize, mode: ClosureMode) -> Result<Execution, String> { let mut session = ReadSession::new(&column.page, mode); c06_get_session(column, row, &mut session) }

pub fn c06_sum_session(column: &EncodedColumn, rows: Span, session: &mut ReadSession<'_>) -> Result<Execution, String> {
    if rows.start > rows.end || rows.end > column.truth.len() { return Err("generated SUM range invalid".into()); }
    load_metadata(&column.page, session)?; let mut sum = 0_i128; let mut decoded_rows = 0;
    c06_n2_visit(session, rows.start, rows.end, &mut |_session, value, start, end| { decoded_rows += end - start; if let Some(value) = value { sum = sum.checked_add(value.checked_mul((end - start) as i128).ok_or("generated SUM product overflow")?).ok_or("generated SUM overflow")?; } Ok(()) })?;
    Ok(Execution { answer: Answer::Sum(sum), metrics: session.metrics(), decoded_rows })
}

pub fn c06_sum(column: &EncodedColumn, rows: Span, mode: ClosureMode) -> Result<Execution, String> { let mut session = ReadSession::new(&column.page, mode); c06_sum_session(column, rows, &mut session) }

pub fn c06_between_session(column: &EncodedColumn, rows: Span, low: i64, high: i64, session: &mut ReadSession<'_>) -> Result<Execution, String> {
    if rows.start > rows.end || rows.end > column.truth.len() || low > high { return Err("generated BETWEEN invalid".into()); }
    load_metadata(&column.page, session)?; let mut ranges = Vec::new(); let mut decoded_rows = 0;
    c06_n2_visit(session, rows.start, rows.end, &mut |_session, value, start, end| { decoded_rows += end - start; if value.is_some_and(|value| i128::from(low) <= value && value <= i128::from(high)) { push_range(&mut ranges, start, end); } Ok(()) })?;
    Ok(Execution { answer: Answer::Ranges(ranges), metrics: session.metrics(), decoded_rows })
}

pub fn c06_between(column: &EncodedColumn, rows: Span, low: i64, high: i64, mode: ClosureMode) -> Result<Execution, String> { let mut session = ReadSession::new(&column.page, mode); c06_between_session(column, rows, low, high, &mut session) }

pub fn c06_filter_scan_session(column: &EncodedColumn, low: i64, high: i64, session: &mut ReadSession<'_>) -> Result<Execution, String> { c06_between_session(column, Span::new(0, column.truth.len())?, low, high, session) }
pub fn c06_filter_scan(column: &EncodedColumn, low: i64, high: i64, mode: ClosureMode) -> Result<Execution, String> { let mut session = ReadSession::new(&column.page, mode); c06_filter_scan_session(column, low, high, &mut session) }
pub fn c06_filter_session(column: &EncodedColumn, low: i64, high: i64, session: &mut ReadSession<'_>) -> Result<Execution, String> { c06_filter_scan_session(column, low, high, session) }
