fn c16_validate_ranges(column: &EncodedColumn, ranges: &[Span]) -> Result<(), String> { let mut previous = 0; for range in ranges { if range.start > range.end || range.end > column.truth.len() || range.start < previous { return Err("generated selection ranges are invalid".into()); } previous = range.end; } Ok(()) }
pub fn c16_sum_ranges_session(column: &EncodedColumn, ranges: &[Span], session: &mut ReadSession<'_>) -> Result<Execution, String> {
    c16_validate_ranges(column, ranges)?; load_metadata(&column.page, session)?; let mut sum = 0_i128; let mut decoded_rows = 0;
    for range in ranges { c16_n1_visit(session, range.start, range.end, &mut |_session, value, start, end| { decoded_rows += end - start; if let Some(value) = value { sum = sum.checked_add(value.checked_mul((end - start) as i128).ok_or("generated selected SUM product overflow")?).ok_or("generated selected SUM overflow")?; } Ok(()) })?; }
    Ok(Execution { answer: Answer::Sum(sum), metrics: session.metrics(), decoded_rows }) }
pub fn c16_sum_ranges(column: &EncodedColumn, ranges: &[Span], mode: ClosureMode) -> Result<Execution, String> { let mut session = ReadSession::new(&column.page, mode); c16_sum_ranges_session(column, ranges, &mut session) }

pub fn c16_fused_sum_ranges_session(column: &EncodedColumn, ranges: &[Span], session: &mut ReadSession<'_>) -> Result<Execution, String> {
    c16_validate_ranges(column, ranges)?; load_metadata(&column.page, session)?; let mut sum = 0_i128; let mut decoded_rows = 0; let mut range_index = 0;
    c16_n1_visit(session, 0, column.truth.len(), &mut |_session, value, start, end| { decoded_rows += end - start; while range_index < ranges.len() && ranges[range_index].end <= start { range_index += 1; } let mut probe = range_index; while probe < ranges.len() && ranges[probe].start < end { let overlap_start = start.max(ranges[probe].start); let overlap_end = end.min(ranges[probe].end); if overlap_start < overlap_end && let Some(value) = value { sum = sum.checked_add(value.checked_mul((overlap_end - overlap_start) as i128).ok_or("generated fused selected SUM product overflow")?).ok_or("generated fused selected SUM overflow")?; }
if ranges[probe].end <= end { probe += 1; } else { break; } } range_index = probe; Ok(()) })?;
    Ok(Execution { answer: Answer::Sum(sum), metrics: session.metrics(), decoded_rows }) }
pub fn c16_fused_sum_ranges(column: &EncodedColumn, ranges: &[Span], mode: ClosureMode) -> Result<Execution, String> { let mut session = ReadSession::new(&column.page, mode); c16_fused_sum_ranges_session(column, ranges, &mut session) }

fn c16_materialize(column: &EncodedColumn, mode: ClosureMode) -> Result<(Vec<Option<i128>>, AccessMetrics), String> {
    let mut session = ReadSession::new(&column.page, mode); load_metadata(&column.page, &mut session)?;
    let mut values = Vec::with_capacity(column.truth.len());
    c16_n1_visit(&mut session, 0, column.truth.len(), &mut |_session, value, start, end| { for _ in start..end { values.push(value); } Ok(()) })?;
    if values.len() != column.truth.len() { return Err("generated materializer returned the wrong row count".into()); }
    Ok((values, session.metrics()))
}

pub fn c16_materialized_get(column: &EncodedColumn, row: usize, mode: ClosureMode) -> Result<Execution, String> {
    if row >= column.truth.len() { return Err("materialized GET outside column".into()); } let (values, metrics) = c16_materialize(column, mode)?;
    let value = values[row].map(|value| i64::try_from(value).map_err(|_| "materialized GET value does not fit i64")).transpose()?;
    Ok(Execution { answer: Answer::Value(value), metrics, decoded_rows: values.len() })
}

pub fn c16_materialized_sum(column: &EncodedColumn, rows: Span, mode: ClosureMode) -> Result<Execution, String> {
    if rows.start > rows.end || rows.end > column.truth.len() { return Err("materialized SUM range invalid".into()); } let (values, metrics) = c16_materialize(column, mode)?; let mut sum = 0_i128;
    for value in values[rows.start..rows.end].iter().flatten() { sum = sum.checked_add(*value).ok_or("materialized SUM overflow")?; }
    Ok(Execution { answer: Answer::Sum(sum), metrics, decoded_rows: values.len() })
}

pub fn c16_materialized_between(column: &EncodedColumn, rows: Span, low: i64, high: i64, mode: ClosureMode) -> Result<Execution, String> {
    if rows.start > rows.end || rows.end > column.truth.len() || low > high { return Err("materialized BETWEEN invalid".into()); } let (values, metrics) = c16_materialize(column, mode)?; let mut ranges = Vec::new();
    for (offset, value) in values[rows.start..rows.end].iter().enumerate() { if value.is_some_and(|value| i128::from(low) <= value && value <= i128::from(high)) { let row = rows.start + offset; push_range(&mut ranges, row, row + 1); } }
    Ok(Execution { answer: Answer::Ranges(ranges), metrics, decoded_rows: values.len() })
}

pub fn c16_fused_get_session(column: &EncodedColumn, row: usize, session: &mut ReadSession<'_>) -> Result<Execution, String> {
    if row >= column.truth.len() { return Err("fused GET outside column".into()); } load_metadata(&column.page, session)?; let mut answer = None; let mut decoded_rows = 0;
    c16_n1_visit(session, 0, column.truth.len(), &mut |_session, value, start, end| { decoded_rows += end - start; if start <= row && row < end { answer = Some(value.map(|value| i64::try_from(value).map_err(|_| "fused GET value does not fit i64")).transpose()?); } Ok(()) })?;
    Ok(Execution { answer: Answer::Value(answer.ok_or("fused GET missed row")?), metrics: session.metrics(), decoded_rows })
}

