    for range in ranges { c24_n1_visit(session, range.start, range.end, &mut |_session, value, start, end| { decoded_rows += end - start; if let Some(value) = value { sum = sum.checked_add(value.checked_mul((end - start) as i128).ok_or("generated selected SUM product overflow")?).ok_or("generated selected SUM overflow")?; } Ok(()) })?; }
