pub const C26_PLAN_SIGNATURE: u64 = 0x06922926e9665f1c;
type C26N0Static = StaticBitPack<2, 8, 128, 128>;
#[inline(always)]
fn c26_n0_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    Ok(Some(i128::from(session.read_bits(FieldId(2), row, 8, 128, 128)?)))
}

#[inline(always)]
fn c26_n0_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    let values = session.read_bit_values(FieldId(2), Span::new(start, end)?, 8, 128, 128)?;
    for (offset, value) in values.into_iter().enumerate() { let row = start + offset; visitor(session, Some(i128::from(value)), row, row + 1)?; }
    Ok(())
}

type C26N1Static = StaticDictionary<1, 175, C26N0Static>;
#[inline(always)]
fn c26_n1_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    let id = usize::try_from(c26_n0_get(session, row)?.ok_or("generated dictionary id is null")?).map_err(|_| "generated dictionary id does not fit usize")?;
    if id >= 175 { return Err("generated dictionary id is outside table".into()); }
    Ok(Some(i128::from(session.read_i64(FieldId(1), id)?)))
}

#[inline(always)]
fn c26_n1_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    c26_n0_visit(session, start, end, &mut |session, id, span_start, span_end| {
        let id = usize::try_from(id.ok_or("generated dictionary id is null")?).map_err(|_| "generated dictionary id does not fit usize")?;
        if id >= 175 { return Err("generated dictionary id is outside table".into()); }
        let value = Some(i128::from(session.read_i64(FieldId(1), id)?)); visitor(session, value, span_start, span_end)
    })
}

