pub fn c26_filter_session(column: &EncodedColumn, low: i64, high: i64, session: &mut ReadSession<'_>) -> Result<Execution, String> {
    if low > high { return Err("generated FILTER bounds are invalid".into()); } load_metadata(&column.page, session)?;
    let mut left = 0; let mut right = 175; while left < right { let mid = left + (right - left) / 2; if session.read_i64(FieldId(1), mid)? < low { left = mid + 1; } else { right = mid; } } let low_id = left;
    right = 175; while left < right { let mid = left + (right - left) / 2; if session.read_i64(FieldId(1), mid)? <= high { left = mid + 1; } else { right = mid; } } let high_id = left;
    let mut ranges = Vec::new(); let mut decoded_rows = 0; if low_id < high_id { c26_n0_visit(session, 0, column.truth.len(), &mut |_session, id, start, end| { decoded_rows += end - start; let id = usize::try_from(id.ok_or("generated dictionary id is null")?).map_err(|_| "generated dictionary id does not fit usize")?; if id >= 175 { return Err("generated dictionary id is outside table".into()); }
if low_id <= id && id < high_id { push_range(&mut ranges, start, end); } Ok(()) })?; }
    Ok(Execution { answer: Answer::Ranges(ranges), metrics: session.metrics(), decoded_rows }) }
