pub const C38_PLAN_SIGNATURE: u64 = 0x6f936b4fc9fb17f9;
type C38N0Static = StaticBitPack<2, 8, 128, 128>;
#[inline(always)]
fn c38_n0_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    Ok(Some(i128::from(session.read_bits(FieldId(2), row, 8, 128, 128)?)))
}

#[inline(always)]
fn c38_n0_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    let values = session.read_bit_values(FieldId(2), Span::new(start, end)?, 8, 128, 128)?;
    for (offset, value) in values.into_iter().enumerate() { let row = start + offset; visitor(session, Some(i128::from(value)), row, row + 1)?; }
    Ok(())
}

type C38N1Static = StaticDictionary<1, 224, C38N0Static>;
#[inline(always)]
fn c38_n1_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    let id = usize::try_from(c38_n0_get(session, row)?.ok_or("generated dictionary id is null")?).map_err(|_| "generated dictionary id does not fit usize")?;
    if id >= 224 { return Err("generated dictionary id is outside table".into()); }
    Ok(Some(i128::from(session.read_i64(FieldId(1), id)?)))
}

#[inline(always)]
fn c38_n1_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    c38_n0_visit(session, start, end, &mut |session, id, span_start, span_end| {
        let id = usize::try_from(id.ok_or("generated dictionary id is null")?).map_err(|_| "generated dictionary id does not fit usize")?;
        if id >= 224 { return Err("generated dictionary id is outside table".into()); }
        let value = Some(i128::from(session.read_i64(FieldId(1), id)?)); visitor(session, value, span_start, span_end)
    })
}

pub fn c38_get_session(column: &EncodedColumn, row: usize, session: &mut ReadSession<'_>) -> Result<Execution, String> {
    if row >= column.truth.len() { return Err("generated GET outside column".into()); }
    load_metadata(&column.page, session)?;
    let value = c38_n1_get(session, row)?.map(|value| i64::try_from(value).map_err(|_| "generated GET value does not fit i64")).transpose()?;
    Ok(Execution { answer: Answer::Value(value), metrics: session.metrics(), decoded_rows: 1 })
}

pub fn c38_get(column: &EncodedColumn, row: usize, mode: ClosureMode) -> Result<Execution, String> { let mut session = ReadSession::new(&column.page, mode); c38_get_session(column, row, &mut session) }

pub fn c38_sum_session(column: &EncodedColumn, rows: Span, session: &mut ReadSession<'_>) -> Result<Execution, String> {
    if rows.start > rows.end || rows.end > column.truth.len() { return Err("generated SUM range invalid".into()); }
    load_metadata(&column.page, session)?; let mut sum = 0_i128; let mut decoded_rows = 0;
    c38_n1_visit(session, rows.start, rows.end, &mut |_session, value, start, end| { decoded_rows += end - start; if let Some(value) = value { sum = sum.checked_add(value.checked_mul((end - start) as i128).ok_or("generated SUM product overflow")?).ok_or("generated SUM overflow")?; } Ok(()) })?;
    Ok(Execution { answer: Answer::Sum(sum), metrics: session.metrics(), decoded_rows })
}

pub fn c38_sum(column: &EncodedColumn, rows: Span, mode: ClosureMode) -> Result<Execution, String> { let mut session = ReadSession::new(&column.page, mode); c38_sum_session(column, rows, &mut session) }

pub fn c38_between_session(column: &EncodedColumn, rows: Span, low: i64, high: i64, session: &mut ReadSession<'_>) -> Result<Execution, String> {
    if rows.start > rows.end || rows.end > column.truth.len() || low > high { return Err("generated BETWEEN invalid".into()); }
    load_metadata(&column.page, session)?; let mut ranges = Vec::new(); let mut decoded_rows = 0;
    c38_n1_visit(session, rows.start, rows.end, &mut |_session, value, start, end| { decoded_rows += end - start; if value.is_some_and(|value| i128::from(low) <= value && value <= i128::from(high)) { push_range(&mut ranges, start, end); } Ok(()) })?;
    Ok(Execution { answer: Answer::Ranges(ranges), metrics: session.metrics(), decoded_rows })
}

pub fn c38_between(column: &EncodedColumn, rows: Span, low: i64, high: i64, mode: ClosureMode) -> Result<Execution, String> { let mut session = ReadSession::new(&column.page, mode); c38_between_session(column, rows, low, high, &mut session) }

pub fn c38_filter_scan_session(column: &EncodedColumn, low: i64, high: i64, session: &mut ReadSession<'_>) -> Result<Execution, String> { c38_between_session(column, Span::new(0, column.truth.len())?, low, high, session) }
pub fn c38_filter_scan(column: &EncodedColumn, low: i64, high: i64, mode: ClosureMode) -> Result<Execution, String> { let mut session = ReadSession::new(&column.page, mode); c38_filter_scan_session(column, low, high, &mut session) }
pub fn c38_filter_session(column: &EncodedColumn, low: i64, high: i64, session: &mut ReadSession<'_>) -> Result<Execution, String> {
    if low > high { return Err("generated FILTER bounds are invalid".into()); } load_metadata(&column.page, session)?;
    let mut left = 0; let mut right = 224; while left < right { let mid = left + (right - left) / 2; if session.read_i64(FieldId(1), mid)? < low { left = mid + 1; } else { right = mid; } } let low_id = left;
    right = 224; while left < right { let mid = left + (right - left) / 2; if session.read_i64(FieldId(1), mid)? <= high { left = mid + 1; } else { right = mid; } } let high_id = left;
    let mut ranges = Vec::new(); let mut decoded_rows = 0; if low_id < high_id { c38_n0_visit(session, 0, column.truth.len(), &mut |_session, id, start, end| { decoded_rows += end - start; let id = usize::try_from(id.ok_or("generated dictionary id is null")?).map_err(|_| "generated dictionary id does not fit usize")?; if id >= 224 { return Err("generated dictionary id is outside table".into()); }
if low_id <= id && id < high_id { push_range(&mut ranges, start, end); } Ok(()) })?; }
    Ok(Execution { answer: Answer::Ranges(ranges), metrics: session.metrics(), decoded_rows }) }
pub fn c38_filter(column: &EncodedColumn, low: i64, high: i64, mode: ClosureMode) -> Result<Execution, String> { let mut session = ReadSession::new(&column.page, mode); c38_filter_session(column, low, high, &mut session) }

fn c38_validate_ranges(column: &EncodedColumn, ranges: &[Span]) -> Result<(), String> { let mut previous = 0; for range in ranges { if range.start > range.end || range.end > column.truth.len() || range.start < previous { return Err("generated selection ranges are invalid".into()); } previous = range.end; } Ok(()) }
pub fn c38_sum_ranges_session(column: &EncodedColumn, ranges: &[Span], session: &mut ReadSession<'_>) -> Result<Execution, String> {
    c38_validate_ranges(column, ranges)?; load_metadata(&column.page, session)?; let mut sum = 0_i128; let mut decoded_rows = 0;
    for range in ranges { c38_n1_visit(session, range.start, range.end, &mut |_session, value, start, end| { decoded_rows += end - start; if let Some(value) = value { sum = sum.checked_add(value.checked_mul((end - start) as i128).ok_or("generated selected SUM product overflow")?).ok_or("generated selected SUM overflow")?; } Ok(()) })?; }
    Ok(Execution { answer: Answer::Sum(sum), metrics: session.metrics(), decoded_rows }) }
pub fn c38_sum_ranges(column: &EncodedColumn, ranges: &[Span], mode: ClosureMode) -> Result<Execution, String> { let mut session = ReadSession::new(&column.page, mode); c38_sum_ranges_session(column, ranges, &mut session) }

pub fn c38_fused_sum_ranges_session(column: &EncodedColumn, ranges: &[Span], session: &mut ReadSession<'_>) -> Result<Execution, String> {
    c38_validate_ranges(column, ranges)?; load_metadata(&column.page, session)?; let mut sum = 0_i128; let mut decoded_rows = 0; let mut range_index = 0;
    c38_n1_visit(session, 0, column.truth.len(), &mut |_session, value, start, end| { decoded_rows += end - start; while range_index < ranges.len() && ranges[range_index].end <= start { range_index += 1; } let mut probe = range_index; while probe < ranges.len() && ranges[probe].start < end { let overlap_start = start.max(ranges[probe].start); let overlap_end = end.min(ranges[probe].end); if overlap_start < overlap_end && let Some(value) = value { sum = sum.checked_add(value.checked_mul((overlap_end - overlap_start) as i128).ok_or("generated fused selected SUM product overflow")?).ok_or("generated fused selected SUM overflow")?; }
if ranges[probe].end <= end { probe += 1; } else { break; } } range_index = probe; Ok(()) })?;
    Ok(Execution { answer: Answer::Sum(sum), metrics: session.metrics(), decoded_rows }) }
pub fn c38_fused_sum_ranges(column: &EncodedColumn, ranges: &[Span], mode: ClosureMode) -> Result<Execution, String> { let mut session = ReadSession::new(&column.page, mode); c38_fused_sum_ranges_session(column, ranges, &mut session) }

fn c38_materialize(column: &EncodedColumn, mode: ClosureMode) -> Result<(Vec<Option<i128>>, AccessMetrics), String> {
    let mut session = ReadSession::new(&column.page, mode); load_metadata(&column.page, &mut session)?;
    let mut values = Vec::with_capacity(column.truth.len());
    c38_n1_visit(&mut session, 0, column.truth.len(), &mut |_session, value, start, end| { for _ in start..end { values.push(value); } Ok(()) })?;
    if values.len() != column.truth.len() { return Err("generated materializer returned the wrong row count".into()); }
    Ok((values, session.metrics()))
}

pub fn c38_materialized_get(column: &EncodedColumn, row: usize, mode: ClosureMode) -> Result<Execution, String> {
    if row >= column.truth.len() { return Err("materialized GET outside column".into()); } let (values, metrics) = c38_materialize(column, mode)?;
    let value = values[row].map(|value| i64::try_from(value).map_err(|_| "materialized GET value does not fit i64")).transpose()?;
    Ok(Execution { answer: Answer::Value(value), metrics, decoded_rows: values.len() })
}

pub fn c38_materialized_sum(column: &EncodedColumn, rows: Span, mode: ClosureMode) -> Result<Execution, String> {
    if rows.start > rows.end || rows.end > column.truth.len() { return Err("materialized SUM range invalid".into()); } let (values, metrics) = c38_materialize(column, mode)?; let mut sum = 0_i128;
    for value in values[rows.start..rows.end].iter().flatten() { sum = sum.checked_add(*value).ok_or("materialized SUM overflow")?; }
    Ok(Execution { answer: Answer::Sum(sum), metrics, decoded_rows: values.len() })
}

pub fn c38_materialized_between(column: &EncodedColumn, rows: Span, low: i64, high: i64, mode: ClosureMode) -> Result<Execution, String> {
    if rows.start > rows.end || rows.end > column.truth.len() || low > high { return Err("materialized BETWEEN invalid".into()); } let (values, metrics) = c38_materialize(column, mode)?; let mut ranges = Vec::new();
    for (offset, value) in values[rows.start..rows.end].iter().enumerate() { if value.is_some_and(|value| i128::from(low) <= value && value <= i128::from(high)) { let row = rows.start + offset; push_range(&mut ranges, row, row + 1); } }
    Ok(Execution { answer: Answer::Ranges(ranges), metrics, decoded_rows: values.len() })
}

pub fn c38_fused_get_session(column: &EncodedColumn, row: usize, session: &mut ReadSession<'_>) -> Result<Execution, String> {
    if row >= column.truth.len() { return Err("fused GET outside column".into()); } load_metadata(&column.page, session)?; let mut answer = None; let mut decoded_rows = 0;
    c38_n1_visit(session, 0, column.truth.len(), &mut |_session, value, start, end| { decoded_rows += end - start; if start <= row && row < end { answer = Some(value.map(|value| i64::try_from(value).map_err(|_| "fused GET value does not fit i64")).transpose()?); } Ok(()) })?;
    Ok(Execution { answer: Answer::Value(answer.ok_or("fused GET missed row")?), metrics: session.metrics(), decoded_rows })
}

pub fn c38_fused_get(column: &EncodedColumn, row: usize, mode: ClosureMode) -> Result<Execution, String> { let mut session = ReadSession::new(&column.page, mode); c38_fused_get_session(column, row, &mut session) }

pub fn c38_fused_sum_session(column: &EncodedColumn, rows: Span, session: &mut ReadSession<'_>) -> Result<Execution, String> {
    if rows.start > rows.end || rows.end > column.truth.len() { return Err("fused SUM range invalid".into()); } load_metadata(&column.page, session)?; let mut sum = 0_i128; let mut decoded_rows = 0;
    c38_n1_visit(session, 0, column.truth.len(), &mut |_session, value, start, end| { decoded_rows += end - start; let overlap_start = start.max(rows.start); let overlap_end = end.min(rows.end); if overlap_start < overlap_end && let Some(value) = value { sum = sum.checked_add(value.checked_mul((overlap_end - overlap_start) as i128).ok_or("fused SUM product overflow")?).ok_or("fused SUM overflow")?; } Ok(()) })?;
    Ok(Execution { answer: Answer::Sum(sum), metrics: session.metrics(), decoded_rows })
}

pub fn c38_fused_sum(column: &EncodedColumn, rows: Span, mode: ClosureMode) -> Result<Execution, String> { let mut session = ReadSession::new(&column.page, mode); c38_fused_sum_session(column, rows, &mut session) }

pub fn c38_fused_between_session(column: &EncodedColumn, rows: Span, low: i64, high: i64, session: &mut ReadSession<'_>) -> Result<Execution, String> {
    if rows.start > rows.end || rows.end > column.truth.len() || low > high { return Err("fused BETWEEN invalid".into()); } load_metadata(&column.page, session)?; let mut ranges = Vec::new(); let mut decoded_rows = 0;
    c38_n1_visit(session, 0, column.truth.len(), &mut |_session, value, start, end| { decoded_rows += end - start; let overlap_start = start.max(rows.start); let overlap_end = end.min(rows.end); if overlap_start < overlap_end && value.is_some_and(|value| i128::from(low) <= value && value <= i128::from(high)) { push_range(&mut ranges, overlap_start, overlap_end); } Ok(()) })?;
    Ok(Execution { answer: Answer::Ranges(ranges), metrics: session.metrics(), decoded_rows })
}

pub fn c38_fused_between(column: &EncodedColumn, rows: Span, low: i64, high: i64, mode: ClosureMode) -> Result<Execution, String> { let mut session = ReadSession::new(&column.page, mode); c38_fused_between_session(column, rows, low, high, &mut session) }

