pub fn c57_filter_session(column: &EncodedColumn, low: i64, high: i64, session: &mut ReadSession<'_>) -> Result<Execution, String> {
    if low > high { return Err("generated FILTER bounds are invalid".into()); } load_metadata(&column.page, session)?;
    let mut left = 0; let mut right = 7; while left < right { let mid = left + (right - left) / 2; if session.read_i64(FieldId(1), mid)? < low { left = mid + 1; } else { right = mid; } } let low_id = left;
    right = 7; while left < right { let mid = left + (right - left) / 2; if session.read_i64(FieldId(1), mid)? <= high { left = mid + 1; } else { right = mid; } } let high_id = left;
    let mut ranges = Vec::new(); let mut decoded_rows = 0; if low_id < high_id { c57_n0_visit(session, 0, column.truth.len(), &mut |_session, id, start, end| { decoded_rows += end - start; let id = usize::try_from(id.ok_or("generated dictionary id is null")?).map_err(|_| "generated dictionary id does not fit usize")?; if id >= 7 { return Err("generated dictionary id is outside table".into()); }
if low_id <= id && id < high_id { push_range(&mut ranges, start, end); } Ok(()) })?; }
    Ok(Execution { answer: Answer::Ranges(ranges), metrics: session.metrics(), decoded_rows }) }
pub fn c57_filter(column: &EncodedColumn, low: i64, high: i64, mode: ClosureMode) -> Result<Execution, String> { let mut session = ReadSession::new(&column.page, mode); c57_filter_session(column, low, high, &mut session) }

fn c57_validate_ranges(column: &EncodedColumn, ranges: &[Span]) -> Result<(), String> { let mut previous = 0; for range in ranges { if range.start > range.end || range.end > column.truth.len() || range.start < previous { return Err("generated selection ranges are invalid".into()); } previous = range.end; } Ok(()) }
pub fn c57_sum_ranges_session(column: &EncodedColumn, ranges: &[Span], session: &mut ReadSession<'_>) -> Result<Execution, String> {
    c57_validate_ranges(column, ranges)?; load_metadata(&column.page, session)?; let mut sum = 0_i128; let mut decoded_rows = 0;
    for range in ranges { c57_n1_visit(session, range.start, range.end, &mut |_session, value, start, end| { decoded_rows += end - start; if let Some(value) = value { sum = sum.checked_add(value.checked_mul((end - start) as i128).ok_or("generated selected SUM product overflow")?).ok_or("generated selected SUM overflow")?; } Ok(()) })?; }
    Ok(Execution { answer: Answer::Sum(sum), metrics: session.metrics(), decoded_rows }) }
