fn c61_validate_ranges(column: &EncodedColumn, ranges: &[Span]) -> Result<(), String> { let mut previous = 0; for range in ranges { if range.start > range.end || range.end > column.truth.len() || range.start < previous { return Err("generated selection ranges are invalid".into()); } previous = range.end; } Ok(()) }
pub fn c61_sum_ranges_session(column: &EncodedColumn, ranges: &[Span], session: &mut ReadSession<'_>) -> Result<Execution, String> {
    c61_validate_ranges(column, ranges)?; load_metadata(&column.page, session)?; let mut sum = 0_i128; let mut decoded_rows = 0;
    for range in ranges { c61_n1_visit(session, range.start, range.end, &mut |_session, value, start, end| { decoded_rows += end - start; if let Some(value) = value { sum = sum.checked_add(value.checked_mul((end - start) as i128).ok_or("generated selected SUM product overflow")?).ok_or("generated selected SUM overflow")?; } Ok(()) })?; }
    Ok(Execution { answer: Answer::Sum(sum), metrics: session.metrics(), decoded_rows }) }
pub fn c61_sum_ranges(column: &EncodedColumn, ranges: &[Span], mode: ClosureMode) -> Result<Execution, String> { let mut session = ReadSession::new(&column.page, mode); c61_sum_ranges_session(column, ranges, &mut session) }

pub fn c61_fused_sum_ranges_session(column: &EncodedColumn, ranges: &[Span], session: &mut ReadSession<'_>) -> Result<Execution, String> {
    c61_validate_ranges(column, ranges)?; load_metadata(&column.page, session)?; let mut sum = 0_i128; let mut decoded_rows = 0; let mut range_index = 0;
    c61_n1_visit(session, 0, column.truth.len(), &mut |_session, value, start, end| { decoded_rows += end - start; while range_index < ranges.len() && ranges[range_index].end <= start { range_index += 1; } let mut probe = range_index; while probe < ranges.len() && ranges[probe].start < end { let overlap_start = start.max(ranges[probe].start); let overlap_end = end.min(ranges[probe].end); if overlap_start < overlap_end && let Some(value) = value { sum = sum.checked_add(value.checked_mul((overlap_end - overlap_start) as i128).ok_or("generated fused selected SUM product overflow")?).ok_or("generated fused selected SUM overflow")?; }
if ranges[probe].end <= end { probe += 1; } else { break; } } range_index = probe; Ok(()) })?;
    Ok(Execution { answer: Answer::Sum(sum), metrics: session.metrics(), decoded_rows }) }
pub fn c61_fused_sum_ranges(column: &EncodedColumn, ranges: &[Span], mode: ClosureMode) -> Result<Execution, String> { let mut session = ReadSession::new(&column.page, mode); c61_fused_sum_ranges_session(column, ranges, &mut session) }

fn c61_materialize(column: &EncodedColumn, mode: ClosureMode) -> Result<(Vec<Option<i128>>, AccessMetrics), String> {
    let mut session = ReadSession::new(&column.page, mode); load_metadata(&column.page, &mut session)?;
    let mut values = Vec::with_capacity(column.truth.len());
    c61_n1_visit(&mut session, 0, column.truth.len(), &mut |_session, value, start, end| { for _ in start..end { values.push(value); } Ok(()) })?;
    if values.len() != column.truth.len() { return Err("generated materializer returned the wrong row count".into()); }
    Ok((values, session.metrics()))
}

