    if row >= column.truth.len() { return Err("materialized GET outside column".into()); } let (values, metrics) = c61_materialize(column, mode)?;
    let value = values[row].map(|value| i64::try_from(value).map_err(|_| "materialized GET value does not fit i64")).transpose()?;
