pub const C62_PLAN_SIGNATURE: u64 = 0x10fa69e87af8885f;
type C62N0Static = StaticBitPack<4, 3, 128, 48>;
#[inline(always)]
fn c62_n0_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    Ok(Some(i128::from(session.read_bits(FieldId(4), row, 3, 128, 48)?)))
}

type C62N1Static = StaticFor<3, C62N0Static>;
#[inline(always)]
fn c62_n1_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    let base = i128::from(session.read_i64(FieldId(3), 0)?);
    match c62_n0_get(session, row)? {
        Some(value) => Ok(Some(value.checked_add(base).ok_or("generated FOR overflow")?)),
        None => Ok(None),
    }
}

type C62N2Static = StaticRle<1, 2, 92, 32, C62N1Static>;
#[inline(always)]
fn c62_n2_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    let (run, _, _) = locate_indexed(session, FieldId(2), FieldId(1), 92, 32, row)?;
    c62_n1_get(session, run)
}

#[inline(always)]
fn c62_n2_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    if start == end { return Ok(()); }
    let (mut run, mut run_start, _) = locate_indexed(session, FieldId(2), FieldId(1), 92, 32, start)?;
    while run < 92 && run_start < end {
        let run_end = run_start.checked_add(session.read_u32(FieldId(1), run)? as usize).ok_or("generated RLE row overflow")?;
        let span_start = start.max(run_start);
        let span_end = end.min(run_end);
        if span_start < span_end { let value = c62_n1_get(session, run)?; visitor(session, value, span_start, span_end)?; }
        run_start = run_end; run += 1;
    }
    Ok(())
}

