pub const C63_PLAN_SIGNATURE: u64 = 0x3b042013ffa5ed56;
type C63N0Static = StaticBitPack<2, 51, 128, 816>;
#[inline(always)]
fn c63_n0_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    Ok(Some(i128::from(session.read_bits(FieldId(2), row, 51, 128, 816)?)))
}

#[inline(always)]
fn c63_n0_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    let values = session.read_bit_values(FieldId(2), Span::new(start, end)?, 51, 128, 816)?;
    for (offset, value) in values.into_iter().enumerate() { let row = start + offset; visitor(session, Some(i128::from(value)), row, row + 1)?; }
    Ok(())
}

type C63N1Static = StaticDelta<1, 256, false, C63N0Static>;
#[inline(always)]
fn c63_n1_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    let block = row / 256;
    let block_start = block * 256;
    let mut value = i128::from(session.read_i64(FieldId(1), block)?);
    if block_start < row { c63_n0_visit(session, block_start + 1, row + 1, &mut |_session, code, start, end| {
        let code = u64::try_from(code.ok_or("generated delta code is null")?).map_err(|_| "generated delta code does not fit u64")?;
        let delta = i128::from(unzigzag(code));
        for _ in start..end { value = value.checked_add(delta).ok_or("generated delta overflow")?; } Ok(())
    })?; }
    Ok(Some(value))
}

#[inline(always)]
fn c63_n1_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    let mut block_start = start / 256 * 256;
    while block_start < end {
        let block_end = (block_start + 256).min(end);
        let emit_start = start.max(block_start);
        let mut value = i128::from(session.read_i64(FieldId(1), block_start / 256)?);
        if block_start >= emit_start { visitor(session, Some(value), block_start, block_start + 1)?; }
        if block_start + 1 < block_end { c63_n0_visit(session, block_start + 1, block_end, &mut |session, code, span_start, span_end| {
            let code = u64::try_from(code.ok_or("generated delta code is null")?).map_err(|_| "generated delta code does not fit u64")?;
            let delta = i128::from(unzigzag(code));
            for row in span_start..span_end { value = value.checked_add(delta).ok_or("generated delta span overflow")?; if row >= emit_start { visitor(session, Some(value), row, row + 1)?; } } Ok(())
        })?; }
        block_start += 256;
    }
    Ok(())
}

pub fn c63_get_session(column: &EncodedColumn, row: usize, session: &mut ReadSession<'_>) -> Result<Execution, String> {
    if row >= column.truth.len() { return Err("generated GET outside column".into()); }
    load_metadata(&column.page, session)?;
    let value = c63_n1_get(session, row)?.map(|value| i64::try_from(value).map_err(|_| "generated GET value does not fit i64")).transpose()?;
    Ok(Execution { answer: Answer::Value(value), metrics: session.metrics(), decoded_rows: 1 })
}

pub fn c63_get(column: &EncodedColumn, row: usize, mode: ClosureMode) -> Result<Execution, String> { let mut session = ReadSession::new(&column.page, mode); c63_get_session(column, row, &mut session) }

