pub const C78_PLAN_SIGNATURE: u64 = 0x1b0804f203a9f6db;
type C78N0Static = StaticBitPack<4, 9, 128, 144>;
#[inline(always)]
fn c78_n0_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    Ok(Some(i128::from(session.read_bits(FieldId(4), row, 9, 128, 144)?)))
}

#[inline(always)]
fn c78_n0_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    let values = session.read_bit_values(FieldId(4), Span::new(start, end)?, 9, 128, 144)?;
    for (offset, value) in values.into_iter().enumerate() { let row = start + offset; visitor(session, Some(i128::from(value)), row, row + 1)?; }
    Ok(())
}

type C78N1Static = StaticDictionary<3, 382, C78N0Static>;
#[inline(always)]
fn c78_n1_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    let id = usize::try_from(c78_n0_get(session, row)?.ok_or("generated dictionary id is null")?).map_err(|_| "generated dictionary id does not fit usize")?;
    if id >= 382 { return Err("generated dictionary id is outside table".into()); }
    Ok(Some(i128::from(session.read_i64(FieldId(3), id)?)))
}

#[inline(always)]
fn c78_n1_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    c78_n0_visit(session, start, end, &mut |session, id, span_start, span_end| {
        let id = usize::try_from(id.ok_or("generated dictionary id is null")?).map_err(|_| "generated dictionary id does not fit usize")?;
        if id >= 382 { return Err("generated dictionary id is outside table".into()); }
        let value = Some(i128::from(session.read_i64(FieldId(3), id)?)); visitor(session, value, span_start, span_end)
    })
}

type C78N2Static = StaticNullable<1, 2, 256, C78N1Static>;
#[inline(always)]
fn c78_n2_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    match nullable_rank(session, FieldId(1), FieldId(2), row, 256)? {
        Some(compact_row) => c78_n1_get(session, compact_row),
        None => Ok(None),
    }
}

#[inline(always)]
fn c78_n2_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    let mut logical = start; let mut compact = nullable_prefix_rank(session, FieldId(1), FieldId(2), start, 256)?;
    while logical < end { let valid = nullable_is_valid(session, FieldId(1), logical)?; let run_start = logical; logical += 1; while logical < end && nullable_is_valid(session, FieldId(1), logical)? == valid { logical += 1; }
        if valid { let child_start = compact; compact += logical - run_start; c78_n1_visit(session, child_start, compact, &mut |session, value, span_start, span_end| { let mapped_start = run_start + span_start - child_start; visitor(session, value, mapped_start, mapped_start + span_end - span_start) })?; } else { visitor(session, None, run_start, logical)?; }
    } Ok(())
}

