pub const C80_PLAN_SIGNATURE: u64 = 0x8c589a0f89394e25;
type C80N0Static = StaticBitPack<4, 33, 128, 528>;
#[inline(always)]
fn c80_n0_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    Ok(Some(i128::from(session.read_bits(FieldId(4), row, 33, 128, 528)?)))
}

type C80N1Static = StaticFor<3, C80N0Static>;
#[inline(always)]
fn c80_n1_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    let base = i128::from(session.read_i64(FieldId(3), 0)?);
    match c80_n0_get(session, row)? {
        Some(value) => Ok(Some(value.checked_add(base).ok_or("generated FOR overflow")?)),
        None => Ok(None),
    }
}

type C80N2Static = StaticRle<1, 2, 596, 32, C80N1Static>;
#[inline(always)]
fn c80_n2_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    let (run, _, _) = locate_indexed(session, FieldId(2), FieldId(1), 596, 32, row)?;
    c80_n1_get(session, run)
}

#[inline(always)]
fn c80_n2_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    if start == end { return Ok(()); }
    let (mut run, mut run_start, _) = locate_indexed(session, FieldId(2), FieldId(1), 596, 32, start)?;
    while run < 596 && run_start < end {
        let run_end = run_start.checked_add(session.read_u32(FieldId(1), run)? as usize).ok_or("generated RLE row overflow")?;
        let span_start = start.max(run_start);
        let span_end = end.min(run_end);
        if span_start < span_end { let value = c80_n1_get(session, run)?; visitor(session, value, span_start, span_end)?; }
        run_start = run_end; run += 1;
    }
    Ok(())
}

pub fn c80_get_session(column: &EncodedColumn, row: usize, session: &mut ReadSession<'_>) -> Result<Execution, String> {
    if row >= column.truth.len() { return Err("generated GET outside column".into()); }
    load_metadata(&column.page, session)?;
    let value = c80_n2_get(session, row)?.map(|value| i64::try_from(value).map_err(|_| "generated GET value does not fit i64")).transpose()?;
    Ok(Execution { answer: Answer::Value(value), metrics: session.metrics(), decoded_rows: 1 })
}

