fn c87_n1_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    let base = i128::from(session.read_i64(FieldId(1), 0)?);
    c87_n0_visit(session, start, end, &mut |session, value, span_start, span_end| {
        let value = value.map(|value| value.checked_add(base).ok_or("generated FOR span overflow")).transpose()?;
        visitor(session, value, span_start, span_end)
    })
}

pub fn c87_get_session(column: &EncodedColumn, row: usize, session: &mut ReadSession<'_>) -> Result<Execution, String> {
    if row >= column.truth.len() { return Err("generated GET outside column".into()); }
    load_metadata(&column.page, session)?;
    let value = c87_n1_get(session, row)?.map(|value| i64::try_from(value).map_err(|_| "generated GET value does not fit i64")).transpose()?;
    Ok(Execution { answer: Answer::Value(value), metrics: session.metrics(), decoded_rows: 1 })
}

pub fn c87_get(column: &EncodedColumn, row: usize, mode: ClosureMode) -> Result<Execution, String> { let mut session = ReadSession::new(&column.page, mode); c87_get_session(column, row, &mut session) }

pub fn c87_sum_session(column: &EncodedColumn, rows: Span, session: &mut ReadSession<'_>) -> Result<Execution, String> {
    if rows.start > rows.end || rows.end > column.truth.len() { return Err("generated SUM range invalid".into()); }
    load_metadata(&column.page, session)?; let mut sum = 0_i128; let mut decoded_rows = 0;
    c87_n1_visit(session, rows.start, rows.end, &mut |_session, value, start, end| { decoded_rows += end - start; if let Some(value) = value { sum = sum.checked_add(value.checked_mul((end - start) as i128).ok_or("generated SUM product overflow")?).ok_or("generated SUM overflow")?; } Ok(()) })?;
    Ok(Execution { answer: Answer::Sum(sum), metrics: session.metrics(), decoded_rows })
}

pub fn c87_sum(column: &EncodedColumn, rows: Span, mode: ClosureMode) -> Result<Execution, String> { let mut session = ReadSession::new(&column.page, mode); c87_sum_session(column, rows, &mut session) }

pub fn c87_between_session(column: &EncodedColumn, rows: Span, low: i64, high: i64, session: &mut ReadSession<'_>) -> Result<Execution, String> {
    if rows.start > rows.end || rows.end > column.truth.len() || low > high { return Err("generated BETWEEN invalid".into()); }
    load_metadata(&column.page, session)?; let mut ranges = Vec::new(); let mut decoded_rows = 0;
    c87_n1_visit(session, rows.start, rows.end, &mut |_session, value, start, end| { decoded_rows += end - start; if value.is_some_and(|value| i128::from(low) <= value && value <= i128::from(high)) { push_range(&mut ranges, start, end); } Ok(()) })?;
    Ok(Execution { answer: Answer::Ranges(ranges), metrics: session.metrics(), decoded_rows })
}

pub fn c87_between(column: &EncodedColumn, rows: Span, low: i64, high: i64, mode: ClosureMode) -> Result<Execution, String> { let mut session = ReadSession::new(&column.page, mode); c87_between_session(column, rows, low, high, &mut session) }

pub fn c87_filter_scan_session(column: &EncodedColumn, low: i64, high: i64, session: &mut ReadSession<'_>) -> Result<Execution, String> { c87_between_session(column, Span::new(0, column.truth.len())?, low, high, session) }
pub fn c87_filter_scan(column: &EncodedColumn, low: i64, high: i64, mode: ClosureMode) -> Result<Execution, String> { let mut session = ReadSession::new(&column.page, mode); c87_filter_scan_session(column, low, high, &mut session) }
pub fn c87_filter_session(column: &EncodedColumn, low: i64, high: i64, session: &mut ReadSession<'_>) -> Result<Execution, String> {
    if low > high { return Err("generated FILTER bounds are invalid".into()); } load_metadata(&column.page, session)?; let mut decoded_rows = 0;
    let mut left = 0; let mut right = column.truth.len(); while left < right { let mid = left + (right - left) / 2; let value = c87_n1_get(session, mid)?; decoded_rows += 1; if value.ok_or("dense monotone invariant encountered null")? < i128::from(low) { left = mid + 1; } else { right = mid; } } let start = left;
    right = column.truth.len(); while left < right { let mid = left + (right - left) / 2; let value = c87_n1_get(session, mid)?; decoded_rows += 1; if value.ok_or("dense monotone invariant encountered null")? <= i128::from(high) { left = mid + 1; } else { right = mid; } }
    let ranges = if start < left { vec![Span::new(start, left)?] } else { Vec::new() }; Ok(Execution { answer: Answer::Ranges(ranges), metrics: session.metrics(), decoded_rows }) }
pub fn c87_filter(column: &EncodedColumn, low: i64, high: i64, mode: ClosureMode) -> Result<Execution, String> { let mut session = ReadSession::new(&column.page, mode); c87_filter_session(column, low, high, &mut session) }

fn c87_validate_ranges(column: &EncodedColumn, ranges: &[Span]) -> Result<(), String> { let mut previous = 0; for range in ranges { if range.start > range.end || range.end > column.truth.len() || range.start < previous { return Err("generated selection ranges are invalid".into()); } previous = range.end; } Ok(()) }
pub fn c87_sum_ranges_session(column: &EncodedColumn, ranges: &[Span], session: &mut ReadSession<'_>) -> Result<Execution, String> {
    c87_validate_ranges(column, ranges)?; load_metadata(&column.page, session)?; let mut sum = 0_i128; let mut decoded_rows = 0;
    for range in ranges { c87_n1_visit(session, range.start, range.end, &mut |_session, value, start, end| { decoded_rows += end - start; if let Some(value) = value { sum = sum.checked_add(value.checked_mul((end - start) as i128).ok_or("generated selected SUM product overflow")?).ok_or("generated selected SUM overflow")?; } Ok(()) })?; }
    Ok(Execution { answer: Answer::Sum(sum), metrics: session.metrics(), decoded_rows }) }
pub fn c87_sum_ranges(column: &EncodedColumn, ranges: &[Span], mode: ClosureMode) -> Result<Execution, String> { let mut session = ReadSession::new(&column.page, mode); c87_sum_ranges_session(column, ranges, &mut session) }

pub fn c87_fused_sum_ranges_session(column: &EncodedColumn, ranges: &[Span], session: &mut ReadSession<'_>) -> Result<Execution, String> {
    c87_validate_ranges(column, ranges)?; load_metadata(&column.page, session)?; let mut sum = 0_i128; let mut decoded_rows = 0; let mut range_index = 0;
    c87_n1_visit(session, 0, column.truth.len(), &mut |_session, value, start, end| { decoded_rows += end - start; while range_index < ranges.len() && ranges[range_index].end <= start { range_index += 1; } let mut probe = range_index; while probe < ranges.len() && ranges[probe].start < end { let overlap_start = start.max(ranges[probe].start); let overlap_end = end.min(ranges[probe].end); if overlap_start < overlap_end && let Some(value) = value { sum = sum.checked_add(value.checked_mul((overlap_end - overlap_start) as i128).ok_or("generated fused selected SUM product overflow")?).ok_or("generated fused selected SUM overflow")?; }
if ranges[probe].end <= end { probe += 1; } else { break; } } range_index = probe; Ok(()) })?;
    Ok(Execution { answer: Answer::Sum(sum), metrics: session.metrics(), decoded_rows }) }
pub fn c87_fused_sum_ranges(column: &EncodedColumn, ranges: &[Span], mode: ClosureMode) -> Result<Execution, String> { let mut session = ReadSession::new(&column.page, mode); c87_fused_sum_ranges_session(column, ranges, &mut session) }

fn c87_materialize(column: &EncodedColumn, mode: ClosureMode) -> Result<(Vec<Option<i128>>, AccessMetrics), String> {
    let mut session = ReadSession::new(&column.page, mode); load_metadata(&column.page, &mut session)?;
    let mut values = Vec::with_capacity(column.truth.len());
    c87_n1_visit(&mut session, 0, column.truth.len(), &mut |_session, value, start, end| { for _ in start..end { values.push(value); } Ok(()) })?;
    if values.len() != column.truth.len() { return Err("generated materializer returned the wrong row count".into()); }
    Ok((values, session.metrics()))
}

pub fn c87_materialized_get(column: &EncodedColumn, row: usize, mode: ClosureMode) -> Result<Execution, String> {
    if row >= column.truth.len() { return Err("materialized GET outside column".into()); } let (values, metrics) = c87_materialize(column, mode)?;
    let value = values[row].map(|value| i64::try_from(value).map_err(|_| "materialized GET value does not fit i64")).transpose()?;
    Ok(Execution { answer: Answer::Value(value), metrics, decoded_rows: values.len() })
}

pub fn c87_materialized_sum(column: &EncodedColumn, rows: Span, mode: ClosureMode) -> Result<Execution, String> {
    if rows.start > rows.end || rows.end > column.truth.len() { return Err("materialized SUM range invalid".into()); } let (values, metrics) = c87_materialize(column, mode)?; let mut sum = 0_i128;
    for value in values[rows.start..rows.end].iter().flatten() { sum = sum.checked_add(*value).ok_or("materialized SUM overflow")?; }
    Ok(Execution { answer: Answer::Sum(sum), metrics, decoded_rows: values.len() })
}

pub fn c87_materialized_between(column: &EncodedColumn, rows: Span, low: i64, high: i64, mode: ClosureMode) -> Result<Execution, String> {
    if rows.start > rows.end || rows.end > column.truth.len() || low > high { return Err("materialized BETWEEN invalid".into()); } let (values, metrics) = c87_materialize(column, mode)?; let mut ranges = Vec::new();
    for (offset, value) in values[rows.start..rows.end].iter().enumerate() { if value.is_some_and(|value| i128::from(low) <= value && value <= i128::from(high)) { let row = rows.start + offset; push_range(&mut ranges, row, row + 1); } }
    Ok(Execution { answer: Answer::Ranges(ranges), metrics, decoded_rows: values.len() })
}

pub fn c87_fused_get_session(column: &EncodedColumn, row: usize, session: &mut ReadSession<'_>) -> Result<Execution, String> {
    if row >= column.truth.len() { return Err("fused GET outside column".into()); } load_metadata(&column.page, session)?; let mut answer = None; let mut decoded_rows = 0;
    c87_n1_visit(session, 0, column.truth.len(), &mut |_session, value, start, end| { decoded_rows += end - start; if start <= row && row < end { answer = Some(value.map(|value| i64::try_from(value).map_err(|_| "fused GET value does not fit i64")).transpose()?); } Ok(()) })?;
    Ok(Execution { answer: Answer::Value(answer.ok_or("fused GET missed row")?), metrics: session.metrics(), decoded_rows })
}

pub fn c87_fused_get(column: &EncodedColumn, row: usize, mode: ClosureMode) -> Result<Execution, String> { let mut session = ReadSession::new(&column.page, mode); c87_fused_get_session(column, row, &mut session) }

pub fn c87_fused_sum_session(column: &EncodedColumn, rows: Span, session: &mut ReadSession<'_>) -> Result<Execution, String> {
    if rows.start > rows.end || rows.end > column.truth.len() { return Err("fused SUM range invalid".into()); } load_metadata(&column.page, session)?; let mut sum = 0_i128; let mut decoded_rows = 0;
    c87_n1_visit(session, 0, column.truth.len(), &mut |_session, value, start, end| { decoded_rows += end - start; let overlap_start = start.max(rows.start); let overlap_end = end.min(rows.end); if overlap_start < overlap_end && let Some(value) = value { sum = sum.checked_add(value.checked_mul((overlap_end - overlap_start) as i128).ok_or("fused SUM product overflow")?).ok_or("fused SUM overflow")?; } Ok(()) })?;
    Ok(Execution { answer: Answer::Sum(sum), metrics: session.metrics(), decoded_rows })
}

