pub fn c99_sum_session(column: &EncodedColumn, rows: Span, session: &mut ReadSession<'_>) -> Result<Execution, String> {
    if rows.start > rows.end || rows.end > column.truth.len() { return Err("generated SUM range invalid".into()); }
    load_metadata(&column.page, session)?; let mut sum = 0_i128; let mut decoded_rows = 0;
    c99_n1_visit(session, rows.start, rows.end, &mut |_session, value, start, end| { decoded_rows += end - start; if let Some(value) = value { sum = sum.checked_add(value.checked_mul((end - start) as i128).ok_or("generated SUM product overflow")?).ok_or("generated SUM overflow")?; } Ok(()) })?;
    Ok(Execution { answer: Answer::Sum(sum), metrics: session.metrics(), decoded_rows })
}

