pub const C103_PLAN_SIGNATURE: u64 = 0x8d7594b55702d359;
type C103N0Static = StaticBitPack<2, 20, 128, 320>;
#[inline(always)]
fn c103_n0_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    Ok(Some(i128::from(session.read_bits(FieldId(2), row, 20, 128, 320)?)))
}

#[inline(always)]
fn c103_n0_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    let values = session.read_bit_values(FieldId(2), Span::new(start, end)?, 20, 128, 320)?;
    for (offset, value) in values.into_iter().enumerate() { let row = start + offset; visitor(session, Some(i128::from(value)), row, row + 1)?; }
    Ok(())
}

type C103N1Static = StaticFor<1, C103N0Static>;
#[inline(always)]
fn c103_n1_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    let base = i128::from(session.read_i64(FieldId(1), 0)?);
    match c103_n0_get(session, row)? {
        Some(value) => Ok(Some(value.checked_add(base).ok_or("generated FOR overflow")?)),
        None => Ok(None),
    }
}

#[inline(always)]
fn c103_n1_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    let base = i128::from(session.read_i64(FieldId(1), 0)?);
    c103_n0_visit(session, start, end, &mut |session, value, span_start, span_end| {
        let value = value.map(|value| value.checked_add(base).ok_or("generated FOR span overflow")).transpose()?;
        visitor(session, value, span_start, span_end)
    })
}

