pub const C121_PLAN_SIGNATURE: u64 = 0x8d72010fe87af0a0;
type C121N0Static = StaticBitPack<2, 23, 128, 368>;
#[inline(always)]
fn c121_n0_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    Ok(Some(i128::from(session.read_bits(FieldId(2), row, 23, 128, 368)?)))
}

#[inline(always)]
fn c121_n0_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    let values = session.read_bit_values(FieldId(2), Span::new(start, end)?, 23, 128, 368)?;
    for (offset, value) in values.into_iter().enumerate() { let row = start + offset; visitor(session, Some(i128::from(value)), row, row + 1)?; }
    Ok(())
}

type C121N1Static = StaticFor<1, C121N0Static>;
#[inline(always)]
fn c121_n1_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    let base = i128::from(session.read_i64(FieldId(1), 0)?);
    match c121_n0_get(session, row)? {
        Some(value) => Ok(Some(value.checked_add(base).ok_or("generated FOR overflow")?)),
        None => Ok(None),
    }
}

#[inline(always)]
fn c121_n1_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    let base = i128::from(session.read_i64(FieldId(1), 0)?);
    c121_n0_visit(session, start, end, &mut |session, value, span_start, span_end| {
        let value = value.map(|value| value.checked_add(base).ok_or("generated FOR span overflow")).transpose()?;
        visitor(session, value, span_start, span_end)
    })
}

