pub fn c125_filter_session(column: &EncodedColumn, low: i64, high: i64, session: &mut ReadSession<'_>) -> Result<Execution, String> {
    if low > high { return Err("generated FILTER bounds are invalid".into()); } load_metadata(&column.page, session)?; let mut decoded_rows = 0;
    let mut left = 0; let mut right = column.truth.len(); while left < right { let mid = left + (right - left) / 2; let value = c125_n1_get(session, mid)?; decoded_rows += 1; if value.ok_or("dense monotone invariant encountered null")? < i128::from(low) { left = mid + 1; } else { right = mid; } } let start = left;
    right = column.truth.len(); while left < right { let mid = left + (right - left) / 2; let value = c125_n1_get(session, mid)?; decoded_rows += 1; if value.ok_or("dense monotone invariant encountered null")? <= i128::from(high) { left = mid + 1; } else { right = mid; } }
    let ranges = if start < left { vec![Span::new(start, left)?] } else { Vec::new() }; Ok(Execution { answer: Answer::Ranges(ranges), metrics: session.metrics(), decoded_rows }) }
